  "summary": "The code contains critical security vulnerabilities (LDAP injection) and performance bottlenecks (blocking I/O without connection management). Overall health is poor due to lack of input validation, hardcoded configurations, and improper error handling. The refactored code implements parameterized filtering, connection management, and input validation.",
  "fixed_code": "import os\nfrom flask import request, Flask, abort\nimport ldap\nimport ldap.filter\n\napp = Flask(__name__)\n\ndef get_ldap_user(dc: str, username: str) -> str:\n    # Validate DC against allowlist\n    allowed_dcs = ['example', 'corp']\n    if dc not in allowed_dcs:\n        abort(400, \"Invalid domain component\")\n\n    dn = f\"dc={ldap.filter.escape_filter_chars(dc)}\"\n    search_filter = ldap.filter.filter_format('(user=%s)', [username])\n\n    ldap_url = os.getenv('LDAP_URL', 'ldap://127.0.0.1')\n    conn = ldap.initialize(ldap_url)\n    try:\n        user = conn.search_s(dn, ldap.SCOPE_SUBTREE, search_filter)\n        return str(user) if user else \"User not found\"\n    finally:\n        conn.unbind_s()\n\n@app.route(\"/normal\")\ndef normal() -> str:\n    dc = request.args.get('dc')\n    username = request.args.get('username')\n    \n    if not dc or not username:\n        abort(400, \"Missing required parameters\")\n        \n    return get_ldap_user(dc, username)"
}
